// The table of speeds the make flow offers: every entry a ratio p/q (a plain pair of integers, the
// only thing the renderer knows) and its interval in cents, all worked out here, offline, with
// integers only, so that no pow, exp or log exists anywhere in the contract or in the browser.
//
//   node scripts/ratio-table.mjs            write web/lib/make/ratio-table.ts
//   node scripts/ratio-table.mjs --check    fail if the committed file differs from what this makes
//
// The rule (also printed in the generated file):
//   1. Equal steps. For every 25 cents c from -2400 to 2400, P = round(4096 * 2^(c/1200)), worked out
//      by comparing integer powers (BigInt) so there is no rounding in the rule itself, and the
//      entry is P/4096 in lowest terms. -2400 and 2400 are exactly 1/4 and 4.
//   2. Simple ratios. Every p/q in lowest terms with p and q at most 8 and 1/4 <= p/q <= 4.
//   3. A simple ratio replaces any equal step within 12 cents of it, so the control has no two
//      entries that sound the same.
//   4. Sorted by ratio, no duplicates. Each entry carries its interval in whole cents, the nearest
//      integer to 1200 * log2(p/q), found by comparing (p/q)^2400 with powers of two.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const STEP = 25;
const DENOMINATOR = 4096n;
const SIMPLE_MAX = 8;
const NEAR = 12;
const HALF_OCTAVES = 2400; // two octaves each way: 1/4 .. 4

const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));

/** Nearest whole cent of the interval p/q: the largest c with (p/q)^2400 >= 2^(2c - 1). */
export function centsOf(p, q) {
  const P = BigInt(p) ** 2400n;
  const Q = BigInt(q) ** 2400n;
  const ok = (c) => {
    const e = 2 * c - 1;
    return e >= 0 ? P >= Q << BigInt(e) : P << BigInt(-e) >= Q;
  };
  let lo = -HALF_OCTAVES;
  let hi = HALF_OCTAVES;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (ok(mid)) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/** round(4096 * 2^(c/1200)): the largest P with (2P - 1)^1200 <= 8192^1200 * 2^c. */
function equalStep(c) {
  const base = (2n * DENOMINATOR) ** 1200n;
  const ok = (P) => {
    const left = (2n * P - 1n) ** 1200n;
    return c >= 0 ? left <= base << BigInt(c) : left << BigInt(-c) <= base;
  };
  let lo = 1n;
  let hi = 4n * DENOMINATOR + 1n;
  while (lo < hi) {
    const mid = (lo + hi + 1n) / 2n;
    if (ok(mid)) lo = mid;
    else hi = mid - 1n;
  }
  const d = gcd(lo, DENOMINATOR);
  return [Number(lo / d), Number(DENOMINATOR / d)];
}

export function buildTable() {
  const simple = [];
  for (let p = 1; p <= SIMPLE_MAX; p++) {
    for (let q = 1; q <= SIMPLE_MAX; q++) {
      if (gcd(BigInt(p), BigInt(q)) !== 1n) continue;
      if (p > 4 * q || 4 * p < q) continue;
      simple.push([p, q, centsOf(p, q)]);
    }
  }
  const steps = [];
  for (let c = -HALF_OCTAVES; c <= HALF_OCTAVES; c += STEP) {
    const [p, q] = equalStep(c);
    steps.push([p, q, centsOf(p, q)]);
  }
  const kept = steps.filter(([, , cents]) => !simple.some(([, , s]) => Math.abs(s - cents) <= NEAR));
  const all = [...simple, ...kept].sort((a, b) => a[0] * b[1] - b[0] * a[1]);
  return all.filter((e, i) => i === 0 || e[0] * all[i - 1][1] !== all[i - 1][0] * e[1]);
}

export function renderModule(table) {
  const rows = table.map(([p, q, c]) => `  [${p}, ${q}, ${c}],`).join("\n");
  return `// GENERATED by scripts/ratio-table.mjs: do not edit. \`node scripts/ratio-table.mjs --check\` fails
// when this file differs from what the script makes. The rule is in the script's header.
// Each entry: numerator p, denominator q, and the interval in whole cents of p/q.

export const RATIO_TABLE: ReadonlyArray<readonly [p: number, q: number, cents: number]> = [
${rows}
];
`;
}

const target = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "web", "lib", "make", "ratio-table.ts");

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = renderModule(buildTable());
  if (process.argv.includes("--check")) {
    if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== text) {
      console.error("web/lib/make/ratio-table.ts differs from what scripts/ratio-table.mjs makes");
      process.exit(1);
    }
  } else {
    fs.writeFileSync(target, text);
    console.log(`wrote ${path.relative(process.cwd(), target)}`);
  }
}
